mapper.select:
select count(*)
from round_seat rs
join seat s on rs.seat_id = s.seat_id
where rs.round_id = #{round_id}
and s.seat_group_id = #{seat_group_id}

mapper.update:
UPDATE round_seat SET status = #{status}, reservation_id = #{reservation_id}, preempted_at = #{preempted_at}, reserved_at = #{reserved_at}, canceled_at = #{canceled_at} WHERE round_id = #{round_id} AND seat_id = #{seat_id}
AND status = 'AVAILABLE'
AND status = 'PREEMPTED'
